use xiom.io;

fn classify_temp(celsius: Int) -> Str {
  return match celsius {
    t if t >= 100 => "Boiling",
    t if t >= 30 => "Hot",
    t if t >= 20 => "Warm",
    t if t >= 0 => "Cold",
    _ => "Freezing",
  };
}

fn is_special(n: Int) -> Str {
  return match n {
    x if x % 2 == 0 && x % 3 == 0 => "Special",
    x if x % 2 == 0 => "Even",
    x if x % 3 == 0 => "Divisible by 3",
    _ => "Plain",
  };
}

fn main() -> Int {
  io.println(classify_temp(105).to_str());
  io.println(classify_temp(25).to_str());
  io.println(classify_temp(15).to_str());
  io.println(classify_temp(-5).to_str());
  io.println(is_special(12).to_str());
  io.println(is_special(4).to_str());
  io.println(is_special(9).to_str());
  io.println(is_special(7).to_str());
  return 0;
}
